import{_ as t,o,c as u,ag as e}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第113章 三点十二","description":"","frontmatter":{},"headers":[],"relativePath":"第113章_三点十二.md","filePath":"第113章_三点十二.md"}'),a={name:"第113章_三点十二.md"};function _(q,p,r,n,s,c){return o(),u("div",null,[...p[0]||(p[0]=[e('<h1 id="第113章-三点十二" tabindex="-1">第113章 三点十二 <a class="header-anchor" href="#第113章-三点十二" aria-label="Permalink to &quot;第113章 三点十二&quot;">​</a></h1><p>那年二月五号，她三点十二上线。</p><p>她那边的三点十二，是我这边早上八点十二。</p><p>我在厨房里，我妈在煮东西。</p><p>我手机在手上，屏幕上跳进来一行。</p><p>08:12</p><p>她说：你上班了吗。</p><p>我说：还没，我在厨房。</p><p>她说：那你站着看。</p><p>我说：怎么了。</p><p>她说：我今天三小时以后要睡，我睡不着，我今天要把一件事讲完。</p><p>她说：我今天讲的是我今天早上三点坐在床上想了两个钟头才讲的一句。</p><p>我说：你说。</p><p>她说：我今天讲的是不好听的那种。</p><p>我说：你讲。</p><p>08:15</p><p>她说：我基本上并不喜欢你。</p><p>我站在那里，手里那个碗很烫。</p><p>我妈在那个锅前面拿勺子搅，那个勺子碰锅边的声音我听得一清二楚。</p><p>08:15</p><p>她紧接着发第二句。</p><p>她说：我只是想要被爱。</p><p>我说：你现在说什么。</p><p>她说：我说得很清楚。</p><p>她说：我今天不想讲一句让你再翻译一遍的话。</p><p>08:17</p><p>她说：我这几年，我喜欢的是&quot;你在&quot;。</p><p>她说：这个话我去年不能讲。</p><p>她说：去年我讲了我就得今天来。</p><p>她说：我喜欢的是每天有人跟我讲话。</p><p>她说：我喜欢的是我这边下雨有人问我收没收衣服。</p><p>她说：我喜欢的是我拿一个十九块的杯子，有一个人听我说完我今天为什么买它。</p><p>她说：这些我全部要。</p><p>她说：这些跟你这个人没有关系。</p><p>她说：你换成任何人，只要他每天都回，我要的是那件事。</p><p>我说：那你这些年讲的&quot;我们&quot;。</p><p>她说：我没讲过&quot;我们&quot;。</p><p>我说：你讲过五次。</p><p>她说：你数过。</p><p>我说：我数过。</p><p>她说：那五次我要是不讲，你要难过。</p><p>她说：我讲那五次，是我在照顾你。</p><p>她说：那不是我要的东西。</p><p>08:21</p><p>我妈把那碗东西端到我面前。</p><p>她说吃。</p><p>我说我不饿。</p><p>我妈看了我一眼。</p><p>她说，你现在这个脸色。</p><p>我说，没事。</p><p>我妈把那个碗放在桌上，她没走。</p><p>她站在那里。</p><p>她说，你是不是被人讲了。</p><p>我说，没有。</p><p>她说，你这个人你被人讲了你就站着不动。</p><p>我说，妈，我去上班。</p><p>我妈没让开。</p><p>她说，你吃完。</p><p>08:26</p><p>我端着那个碗走到我屋里。</p><p>我把门带上。</p><p>我坐在桌前，那个粥在手上，我一口没吃。</p><p>屏幕上还在跳。</p><p>她说：你今天不用回我很多。</p><p>她说：我今天就是要讲一遍。</p><p>她说：我这一辈子讲话是讲一遍就收回去的人。</p><p>她说：我今天不收回。</p><p>我说：我知道。</p><p>她说：你知道什么。</p><p>我说：我知道你今天讲的不是气话。</p><p>她说：不是气话。</p><p>她说：我今天没有气。</p><p>她说：我今天很清楚。</p><p>08:30</p><p>我说：那你今天讲了这句，你明天还发货吗。</p><p>她停了很久。</p><p>久到我以为她去睡了。</p><p>08:33</p><p>她说：你这个问题问得很好。</p><p>我说：我问的是实话。</p><p>她说：你问我明天还发货吗。</p><p>她说：我讲了一句我这辈子最狠的一句实话，你回我一句&quot;那货呢&quot;。</p><p>我说：不是。</p><p>我说：我是想知道我们今天讲的是不是一个东西。</p><p>她说：什么意思。</p><p>我说：我要是理解你今天讲的是&quot;我不喜欢你&quot;，那我们两个今天讲的是两件事。</p><p>我说：我要是理解你今天讲的是&quot;我要自由&quot;，那我们两个讲的是同一件。</p><p>她说：哪一种对你更容易？</p><p>我说：第二种。</p><p>她说：那你为什么第二种对你更容易？</p><p>我说：因为第二种我不用难过。</p><p>她说：你看。</p><p>她说：你今天跟我讲的是&quot;哪种你不用难过&quot;。</p><p>她说：我刚才那句&quot;我基本上并不喜欢你&quot;，你第一反应是问货。</p><p>她说：第二反应是问哪种好办。</p><p>她说：你从头到尾没有一句&quot;你为什么会这样想&quot;。</p><p>08:38</p><p>我说：你希望我问。</p><p>她说：我不希望你问。</p><p>我说：为什么。</p><p>她说：因为你要问我就要答。</p><p>她说：我要答我要从头讲。</p><p>她说：我讲了你要开始安慰我。</p><p>她说：我这一辈子被安慰过很多次，安慰完事情还在原地。</p><p>我说：那你要什么。</p><p>她说：我今天什么都不要。</p><p>她说：我今天讲完我三点十二，我四点半要睡，我七点有课。</p><p>她说：我今天讲完我明天还是那个明天。</p><p>她说：我不改任何东西。</p><p>我说：那我改什么。</p><p>她说：你不用改。</p><p>她说：你今天要是改了，你就是因为我讲的这句改的。</p><p>她说：你因为我这句话改，你改三个月你就累了。</p><p>她说：你累了你就要开始跟我讲&quot;我改了呀&quot;。</p><p>她说：我不想要一个&quot;我改了呀&quot;。</p><p>08:42</p><p>我把那碗粥喝了。</p><p>我喝到一半我停下来。</p><p>我屏幕上打了一段。</p><p>我打的是：&quot;那我今天讲一句：我这两年一直在算你欠我多少。&quot;</p><p>我打完我看了一遍。</p><p>我把它删了。</p><p>我删它的原因我今天还记得很清楚。</p><p>我删它是因为我今天删得很快。</p><p>我这一年删东西已经快到没有感觉。</p><p>08:44</p><p>她说：你刚才又删了。</p><p>我说：我没打。</p><p>她说：你输入了四十秒。</p><p>她说：你删了。</p><p>她说：你今天早上八点十二到现在，你删了两次。</p><p>她说：第一删是八点四十一那一段长的。</p><p>她说：你两次我全看见了。</p><p>她说：我今天三点了我睡不着，我今天一直在看你这四个字。</p><p>她说：&quot;对方正在输入中&quot;。</p><p>08:47</p><p>她说：我告诉你我今天为什么讲。</p><p>她说：因为我今天算了一下，我们两个今年要一起过年。</p><p>她说：我要是今天不讲，我二月二十号就要到你那儿。</p><p>她说：我要是到了你那儿，你站在门口，我进门，我今天晚上就要跟你讲一句&quot;我今年不走了&quot;。</p><p>她说：我要是讲了那句，我这辈子就出不来了。</p><p>她说：我不是怕你。</p><p>她说：我是怕我自己会留下来。</p><p>她说：我不配留下来。</p><p>她说：我留下来以后我要靠你，我这一辈子拿一个人我要拿多久我心里有数。</p><p>她说：我拿不了那么久。</p>',146)])])}const l=t(a,[["render",_]]);export{d as __pageData,l as default};
